abstract class Shape {
    abstract double area();

    String name() {
        return getClass().getSimpleName();
    }
}

class Circle extends Shape {
    private final double r;

    Circle(double r) {
        this.r = r;
    }

    @Override
    double area() {
        return Math.PI * r * r;
    }
}

class Rectangle extends Shape {
    private final double w, h;

    Rectangle(double w, double h) {
        this.w = w;
        this.h = h;
    }

    @Override
    double area() {
        return w * h;
    }
}

public class Main {
    public static void main(String[] args) {
        Shape[] shapes = { new Circle(1.0), new Rectangle(4.0, 2.5), new Circle(2.0) };
        double total = 0;
        for (Shape s : shapes) {
            // the overriding area() of the actual object is called (run-time polymorphism)
            System.out.printf("%s area = %.2f%n", s.name(), s.area());
            total += s.area();
        }
        System.out.printf("Total area = %.2f%n", total);
    }
}

model_answer_bn:
