    void show() const { cout << "(" << x << "," << y << ") "; }
};

int main() {
    Point pts[3] = { Point(1, 2), Point(3, 4) };  // pts[2] uses the default constructor
    Point *p = pts;                         // pointer to the first object
    p->move(10);                            // arrow operator
    (p + 1)->move(5);                       // next object in the array
    for (int i = 0; i < 3; i++) pts[i].show();
    cout << endl;

    Point *q = new Point[2];                // array of objects on the heap
