    delete[] q;                             // releases both objects
    cout << endl;
    return 0;
}

Output:
(11,2) (8,4) (0,0) 
(7,8)

p->move(10), pts[0].x-এ 10 যোগ করে (1 → 11), আর (p + 1)->move(5), pts[1].x-এ 5 যোগ করে (3 → 8)। pts[2]-এর কোনো initialiser ছিল না, তাই default constructor একে (0,0) বানিয়েছে।
নোট: new[] থেকে পাওয়া memory delete[] দিয়ে ছাড়তে হয়, কখনো সাধারণ delete বা free() দিয়ে নয়। Java-তে Student[] s = new Student[3]; শুধু 3টি null reference তৈরি করে, তারপর প্রতিটি object new দিয়ে বানাতে হয়।

