A friend function is a non-member function that a class names with the keyword friend, which lets it access the class's private and protected members. It is called like an ordinary function and has no this pointer.

#include <iostream>
using namespace std;

class myclass {
    int num;
public:
    myclass(int i) { num = i; }
    friend bool isneg(myclass ob);   // declaration inside the class
};

// definition: not a member, so no myclass:: and no this pointer
bool isneg(myclass ob) {
    return ob.num < 0;               // may read the private member num
}

int main() {
    myclass a(-10), b(25);
    cout << boolalpha;
    cout << "a is negative: " << isneg(a) << endl;
    cout << "b is negative: " << isneg(b) << endl;
    return 0;
}

