        deposit(list[0], 20000);
        deposit(list[1], 2000, "cash");
        for (Account a : list)                 // overriding: run-time polymorphism
            System.out.println(a.getClass().getSimpleName() + " " + a.getBalance()
                               + " profit " + a.monthlyProfit());
