public class Ticket {
    private static int issued = 0;       // static: one copy for the class
    private static final String PREFIX = "DHK";

    private final int serial;            // instance: one copy per object
    private final String passenger;

    public Ticket(String passenger) {
        issued++;                        // every constructor call counts
        this.serial = issued;
        this.passenger = passenger;
    }

    public static int getIssued() {      // static method: no object needed
        return issued;
    }

    public static String format(int n) { // static helper, uses only static data
        return PREFIX + "-" + n;
    }

    public String describe() {           // instance method: uses both kinds
        return format(serial) + " " + passenger + " (of " + issued + ")";
    }

