import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

public class Lengths {
    // 3. recursion: no loop keyword at all
    static void printLengths(List<String> list, int i) {
        if (i == list.size()) return;
        System.out.println(list.get(i) + " -> " + list.get(i).length());
        printLengths(list, i + 1);
    }

    public static void main(String[] args) {
        List<String> cities = Arrays.asList("Dhaka", "Khulna", "Sylhet", "Cox's Bazar");

        // 1. Stream API: map each string to its length
        List<Integer> lengths = cities.stream()
                                      .map(String::length)
                                      .collect(Collectors.toList());
        System.out.println(lengths);

        // 2. forEach with a lambda
        cities.forEach(s -> System.out.println(s + " = " + s.length()));

        // 3. recursion
        printLengths(cities, 0);

        // 4. a map from each string to its length
        Map<String, Integer> byName = cities.stream()
            .collect(Collectors.toMap(Function.identity(), String::length,
                                      (a, b) -> a, java.util.LinkedHashMap::new));
        System.out.println(byName);
    }
}

Output:
[5, 6, 6, 11]
Dhaka = 5
Khulna = 6
Sylhet = 6
Cox's Bazar = 11
Dhaka -> 5
Khulna -> 6
Sylhet -> 6
Cox's Bazar -> 11
{Dhaka=5, Khulna=6, Sylhet=6, Cox's Bazar=11}

Any one of the four methods answers the question: map(String::length) turns each string into its length; forEach runs a lambda on each element; the recursive method moves to the next index instead of looping; toMap pairs each string with its length.

